export const DICTS: Record<Lang, Dict> = { en, hi, fr, es };

export type Vars = Record<string, string | number>;
export function translate(lang: Lang, key: string, vars: Vars = {}, fallback?: string): string {
  const raw = (DICTS[lang] as Record<string, string>)[key] ?? (en as Record<string, string>)[key] ?? fallback ?? key;
  return raw.replace(/\{(\w+)\}/g, (_, k) => (vars[k] !== undefined ? String(vars[k]) : `{${k}}`));
}

function detect(): Lang {
  try { const s = localStorage.getItem('fl-lang'); if (s && s in DICTS) return s as Lang; } catch { /* storage blocked */ }
  const nav = (typeof navigator !== 'undefined' ? navigator.language : 'en').slice(0, 2);
  return (nav in DICTS ? nav : 'en') as Lang;
}

interface Ctx { lang: Lang; setLang: (l: Lang) => void; t: (key: Key | string, vars?: Vars, fallback?: string) => string }
const I18nCtx = createContext<Ctx>({ lang: 'en', setLang: () => {}, t: (k, v, f) => translate('en', k, v, f) });

export function I18nProvider({ children }: { children: ReactNode }) {
  const [lang, setLang] = useState<Lang>(detect);
  setMoneyLocale(LANGS.find((l) => l.code === lang)!.locale);
  useEffect(() => {
    document.documentElement.lang = lang;
    try { localStorage.setItem('fl-lang', lang); } catch { /* storage blocked */ }
  }, [lang]);
  const value = useMemo<Ctx>(() => ({ lang, setLang, t: (k, v, f) => translate(lang, k, v, f) }), [lang]);
  return createElement(I18nCtx.Provider, { value }, children);
}
export const useI18n = () => useContext(I18nCtx);
